-- Git 세트 54. 여러 번 실행해도 안전하다 (NOT EXISTS 가드). 원본: 02_quest_set.sql, 03_quest_set54.sql, 05_display_order.sql, 06_units.sql, 08_set_icons.sql. docs/specs/spec_foundations_ladder.md
INSERT INTO unit (id, category, title, display_order) SELECT 15, 'Git', '원격과 협업', 30 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM unit WHERE id = 15);
INSERT INTO quest_set (id, title, description, sandbox_type, category)
SELECT 54, 'Git 원격과 협업: 복제하고 올리고 받아오기', '혼자 쓰던 Git 을 팀 작업으로 넓힙니다. 로컬과 원격의 차이, 복제(`clone`), 원격 확인(`remote -v`), 올리기(`push`, `push -u`), 받아오기(`pull`), 안전하게 확인(`fetch`), 거절된 push 풀기, 브랜치로 작업해 올리는 흐름까지 연습합니다. 원격은 샌드박스 안의 로컬 저장소로 대신합니다.', 'linux', 'Git'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest_set WHERE id = 54);
UPDATE quest_set SET display_order = 430, unit_id = (SELECT id FROM unit WHERE id = 15), icon = '🤝' WHERE id = 54;

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 54, 1, '로컬 저장소와 원격 저장소 구분하기', '내 컴퓨터에서 `git commit` 을 했는데 팀원이 아직 그 커밋을 볼 수 없습니다. 왜일까요?', 'Git 은 "내 컴퓨터의 저장소"와 "공용 서버의 저장소"가 따로 있는 분산 구조입니다.', NULL, NULL, '[]', 'choice', '["커밋은 내 컴퓨터(로컬) 저장소에만 기록되고, 원격 저장소로 `git push` 해야 팀원이 받을 수 있다", "커밋하면 자동으로 모든 팀원에게 전달된다", "팀원이 `git add` 를 해야 보인다", "원격 저장소에서는 커밋을 볼 수 없다"]', 0, '`git commit` 은 **내 컴퓨터의 저장소**에 기록할 뿐입니다. 공용 저장소(GitHub, GitLab 같은 원격, 보통 이름 `origin`)로 올리는 것이 `git push`, 원격의 새 커밋을 받아 오는 것이 `git fetch`/`git pull` 입니다.', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 54 AND order_index = 1);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 54, 2, 'fetch 와 pull 의 차이 알기', '`git fetch` 와 `git pull` 의 차이로 알맞은 것은 무엇일까요?', '`pull` 은 두 단계를 한꺼번에 합니다.', NULL, NULL, '[]', 'choice', '["`fetch` 는 원격의 새 이력을 **가져오기만** 하고, `pull` 은 가져온 뒤 지금 브랜치에 **합치기까지** 한다", "`fetch` 는 올리고 `pull` 은 내려받는다", "둘은 완전히 같다", "`pull` 은 원격을 삭제한다"]', 0, '`git pull` = `git fetch` + (합치기: merge 또는 rebase) 입니다. `fetch` 는 내 작업 폴더를 바꾸지 않고 **무엇이 새로 올라왔는지 확인**만 할 수 있어 안전합니다. 현장에서는 fetch 로 먼저 확인한 뒤 합치는 습관이 좋습니다.', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 54 AND order_index = 2);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 54, 3, 'push 가 거절되는 이유 알기', '`git push` 를 했더니 `! [rejected] main -> main (fetch first)` 라고 거절되었습니다. 원인은 무엇일까요?', '메시지의 `fetch first` 는 "먼저 받아 오라"는 뜻입니다.', NULL, NULL, '[]', 'choice', '["원격에 내가 모르는 새 커밋(팀원이 먼저 올린 것)이 있어서, 먼저 받아서 합친 뒤 올려야 한다", "인터넷 연결이 끊어졌다", "커밋 메시지가 너무 길다", "브랜치 이름이 틀렸다"]', 0, '원격의 `main` 이 내 로컬보다 앞서 있으면 Git 은 팀원의 작업을 덮어쓰지 않도록 push 를 막습니다. 해결은 `git pull`(받아서 합치기) → 충돌이 있으면 해결 → 다시 `git push` 입니다. 강제로 올리는 `--force` 는 팀원의 커밋을 지울 수 있어 함부로 쓰지 않습니다.', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 54 AND order_index = 3);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 54, 4, '원격 저장소 복제하기 (git clone)', '원격 저장소가 `/tmp/remote.git` 에 있습니다. 이것을 `/tmp/work` 폴더로 **복제(clone)** 하세요. (실제로는 `git clone https://...` 주소를 씁니다)', '형태는 `git clone 원격주소 폴더` 입니다.
확인: `ls /tmp/work` 와 `git -C /tmp/work log --oneline`', 'git clone /tmp/remote.git /tmp/work

# clone : 원격의 전체 이력을 내려받고 origin 으로 연결한다', '["sh", "-c", "git config --global user.name tester && git config --global user.email tester@example.com && git config --global init.defaultBranch main && rm -rf /tmp/remote.git /tmp/seed /tmp/proj /tmp/work /tmp/mate && git init -q --bare /tmp/remote.git && git clone -q /tmp/remote.git /tmp/seed 2>/dev/null && cd /tmp/seed && printf ''readme\\\\n'' > README.md && git add . && git commit -qm init && git push -q origin main && cd /tmp"]', '["sh", "-c", "( git -C /tmp/work rev-parse --git-dir >/dev/null 2>&1 ) && ( [ -f /tmp/work/README.md ] ) && ( [ \\"$(git -C /tmp/work remote get-url origin)\\" = /tmp/remote.git ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "/tmp/work 가 Git 저장소다", "cmd": ["sh", "-c", "git -C /tmp/work rev-parse --git-dir >/dev/null 2>&1"]}, {"label": "원격의 README.md 가 내려왔다", "cmd": ["sh", "-c", "[ -f /tmp/work/README.md ]"]}, {"label": "origin 이 /tmp/remote.git 이다", "cmd": ["sh", "-c", "[ \\"$(git -C /tmp/work remote get-url origin)\\" = /tmp/remote.git ]"]}]', '[{"title": "Git 공식 문서", "url": "https://git-scm.com/docs"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 54 AND order_index = 4);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 54, 5, '연결된 원격 확인하기 (git remote -v)', '`/tmp/proj` 는 원격에서 복제한 저장소입니다. 이 저장소에 **연결된 원격의 이름과 주소**를 `/tmp/remote.txt` 에 저장하세요.', '찾는 방법: `git remote --help | grep -i verbose`
확인: `cat /tmp/remote.txt` (`origin` 이 보여야 합니다)', 'cd /tmp/proj
git remote -v > /tmp/remote.txt

# -v : 주소까지 자세히
# 가져오기(fetch)와 올리기(push) 줄이 따로 나온다', '["sh", "-c", "git config --global user.name tester && git config --global user.email tester@example.com && git config --global init.defaultBranch main && rm -rf /tmp/remote.git /tmp/seed /tmp/proj /tmp/work /tmp/mate && git init -q --bare /tmp/remote.git && git clone -q /tmp/remote.git /tmp/seed 2>/dev/null && cd /tmp/seed && printf ''readme\\\\n'' > README.md && git add . && git commit -qm init && git push -q origin main && cd /tmp && git clone -q /tmp/remote.git /tmp/proj"]', '["sh", "-c", "( [ -s /tmp/remote.txt ] ) && ( grep -q \\"^origin\\" /tmp/remote.txt ) && ( grep -q \\"/tmp/remote.git\\" /tmp/remote.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "결과 파일 /tmp/remote.txt 가 있다", "cmd": ["sh", "-c", "[ -s /tmp/remote.txt ]"]}, {"label": "origin 이 보인다", "cmd": ["sh", "-c", "grep -q \\"^origin\\" /tmp/remote.txt"]}, {"label": "주소 /tmp/remote.git 이 보인다", "cmd": ["sh", "-c", "grep -q \\"/tmp/remote.git\\" /tmp/remote.txt"]}]', '[{"title": "Git 공식 문서", "url": "https://git-scm.com/docs"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 54 AND order_index = 5);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 54, 6, '내 커밋을 원격에 올리기 (git push)', '`/tmp/proj` 에는 아직 원격에 올리지 않은 커밋(`add feature`)이 있습니다. 이 커밋을 **원격(origin)의 `main`** 에 올리세요.', '형태는 `git push 원격이름 브랜치이름` 입니다. 올리기 전 `git status` 로 "ahead of origin/main" 문구를 보면 올릴 커밋이 있다는 뜻입니다.
확인: `git status`', 'cd /tmp/proj
git push origin main

# push : 내 커밋을 원격으로 올린다', '["sh", "-c", "git config --global user.name tester && git config --global user.email tester@example.com && git config --global init.defaultBranch main && rm -rf /tmp/remote.git /tmp/seed /tmp/proj /tmp/work /tmp/mate && git init -q --bare /tmp/remote.git && git clone -q /tmp/remote.git /tmp/seed 2>/dev/null && cd /tmp/seed && printf ''readme\\\\n'' > README.md && git add . && git commit -qm init && git push -q origin main && cd /tmp && git clone -q /tmp/remote.git /tmp/proj && cd /tmp/proj && echo f > feature.txt && git add . && git commit -qm ''add feature''"]', '["sh", "-c", "( [ \\"$(git --git-dir=/tmp/remote.git log -n 5 --format=%s main | head -n 1)\\" = \\"add feature\\" ] ) && ( cd /tmp/proj && git fetch -q && [ \\"$(git rev-parse HEAD)\\" = \\"$(git rev-parse origin/main)\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "원격 main 의 최신 커밋이 `add feature` 이다", "cmd": ["sh", "-c", "[ \\"$(git --git-dir=/tmp/remote.git log -n 5 --format=%s main | head -n 1)\\" = \\"add feature\\" ]"]}, {"label": "내 main 과 원격이 같다 (올릴 것이 없다)", "cmd": ["sh", "-c", "cd /tmp/proj && git fetch -q && [ \\"$(git rev-parse HEAD)\\" = \\"$(git rev-parse origin/main)\\" ]"]}]', '[{"title": "Git 공식 문서", "url": "https://git-scm.com/docs"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 54 AND order_index = 6);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 54, 7, '새 브랜치를 원격에 올리고 연결하기 (push -u)', '`/tmp/proj` 에서 **`feature/x`** 브랜치를 만들고 `x.txt` 를 **`add x`** 로 커밋한 뒤, 이 브랜치를 원격에 올리면서 **추적(upstream) 연결**까지 하세요. 이후 `git push` 만 쳐도 올라가야 합니다.', '새 브랜치를 처음 올릴 때는 원격 이름과 브랜치 이름을 적고, 연결(`--set-upstream`, 줄여서 `-u`) 옵션을 붙입니다.
확인: `git status` (`Your branch is up to date with origin/feature/x`)', 'cd /tmp/proj
git switch -c feature/x
echo x > x.txt
git add x.txt
git commit -m "add x"
git push -u origin feature/x

# -u : 이 브랜치와 원격 브랜치를 연결해 다음부터 git push/pull 만 써도 된다', '["sh", "-c", "git config --global user.name tester && git config --global user.email tester@example.com && git config --global init.defaultBranch main && rm -rf /tmp/remote.git /tmp/seed /tmp/proj /tmp/work /tmp/mate && git init -q --bare /tmp/remote.git && git clone -q /tmp/remote.git /tmp/seed 2>/dev/null && cd /tmp/seed && printf ''readme\\\\n'' > README.md && git add . && git commit -qm init && git push -q origin main && cd /tmp && git clone -q /tmp/remote.git /tmp/proj"]', '["sh", "-c", "( git --git-dir=/tmp/remote.git rev-parse --verify -q feature/x >/dev/null ) && ( [ \\"$(git --git-dir=/tmp/remote.git log -n 5 --format=%s feature/x | head -n 1)\\" = \\"add x\\" ] ) && ( cd /tmp/proj && [ \\"$(git rev-parse --abbrev-ref feature/x@{upstream})\\" = origin/feature/x ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "원격에 feature/x 브랜치가 있다", "cmd": ["sh", "-c", "git --git-dir=/tmp/remote.git rev-parse --verify -q feature/x >/dev/null"]}, {"label": "원격 feature/x 의 최신 커밋이 `add x` 이다", "cmd": ["sh", "-c", "[ \\"$(git --git-dir=/tmp/remote.git log -n 5 --format=%s feature/x | head -n 1)\\" = \\"add x\\" ]"]}, {"label": "upstream 이 origin/feature/x 로 연결되었다", "cmd": ["sh", "-c", "cd /tmp/proj && [ \\"$(git rev-parse --abbrev-ref feature/x@{upstream})\\" = origin/feature/x ]"]}]', '[{"title": "Git 공식 문서", "url": "https://git-scm.com/docs"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 54 AND order_index = 7);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 54, 8, '팀원의 새 커밋 받아오기 (git pull)', '팀원이 원격 `main` 에 `mate.txt` 를 추가하는 커밋(`mate commit`)을 올렸습니다. `/tmp/proj` 에서 이 커밋을 **받아서 내 `main` 에 반영**하세요.', '`git pull` 은 가져오기와 합치기를 한 번에 합니다. 이미 연결된 브랜치이므로 이름은 생략할 수 있습니다.
확인: `ls /tmp/proj` (`mate.txt` 가 보여야 합니다)', 'cd /tmp/proj
git pull

# pull = fetch + merge', '["sh", "-c", "git config --global user.name tester && git config --global user.email tester@example.com && git config --global init.defaultBranch main && rm -rf /tmp/remote.git /tmp/seed /tmp/proj /tmp/work /tmp/mate && git init -q --bare /tmp/remote.git && git clone -q /tmp/remote.git /tmp/seed 2>/dev/null && cd /tmp/seed && printf ''readme\\\\n'' > README.md && git add . && git commit -qm init && git push -q origin main && cd /tmp && git clone -q /tmp/remote.git /tmp/proj && git clone -q /tmp/remote.git /tmp/mate && cd /tmp/mate && echo m > mate.txt && git add . && git commit -qm ''mate commit'' && git push -q origin main && cd /tmp"]', '["sh", "-c", "( [ -f /tmp/proj/mate.txt ] ) && ( cd /tmp/proj && [ \\"$(git rev-parse HEAD)\\" = \\"$(git rev-parse origin/main)\\" ] ) && ( cd /tmp/proj && git log --format=%s | grep -qx \\"mate commit\\" )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "mate.txt 가 내려왔다", "cmd": ["sh", "-c", "[ -f /tmp/proj/mate.txt ]"]}, {"label": "내 main 이 원격과 같다", "cmd": ["sh", "-c", "cd /tmp/proj && [ \\"$(git rev-parse HEAD)\\" = \\"$(git rev-parse origin/main)\\" ]"]}, {"label": "`mate commit` 이 내 이력에 있다", "cmd": ["sh", "-c", "cd /tmp/proj && git log --format=%s | grep -qx \\"mate commit\\""]}]', '[{"title": "Git 공식 문서", "url": "https://git-scm.com/docs"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 54 AND order_index = 8);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 54, 9, '합치기 전에 무엇이 올라왔는지 먼저 보기 (fetch)', '팀원이 원격 `main` 에 새 커밋을 올렸습니다. `/tmp/proj` 의 **작업 폴더는 건드리지 않고** 새 커밋이 무엇인지만 확인하세요. 원격에만 있는 커밋을 한 줄 형식으로 `/tmp/incoming.txt` 에 저장하세요. (`mate.txt` 파일은 아직 내려오면 안 됩니다)', '1) 안전하게 가져오기: `git fetch` 2) "내 main 에는 없고 원격 main 에만 있는 커밋": `git log main..origin/main --oneline`.
확인: `ls /tmp/proj` (mate.txt 가 없어야 합니다)', 'cd /tmp/proj
git fetch
git log main..origin/main --oneline > /tmp/incoming.txt

# fetch 는 작업 폴더를 바꾸지 않는다
# A..B : B 에는 있고 A 에는 없는 커밋', '["sh", "-c", "git config --global user.name tester && git config --global user.email tester@example.com && git config --global init.defaultBranch main && rm -rf /tmp/remote.git /tmp/seed /tmp/proj /tmp/work /tmp/mate && git init -q --bare /tmp/remote.git && git clone -q /tmp/remote.git /tmp/seed 2>/dev/null && cd /tmp/seed && printf ''readme\\\\n'' > README.md && git add . && git commit -qm init && git push -q origin main && cd /tmp && git clone -q /tmp/remote.git /tmp/proj && git clone -q /tmp/remote.git /tmp/mate && cd /tmp/mate && echo m > mate.txt && git add . && git commit -qm ''mate commit'' && git push -q origin main && cd /tmp"]', '["sh", "-c", "( [ -s /tmp/incoming.txt ] ) && ( [ \\"$(wc -l < /tmp/incoming.txt)\\" -eq 1 ] && grep -q \\"mate commit\\" /tmp/incoming.txt ) && ( [ ! -f /tmp/proj/mate.txt ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "결과 파일 /tmp/incoming.txt 가 있다", "cmd": ["sh", "-c", "[ -s /tmp/incoming.txt ]"]}, {"label": "원격에만 있는 `mate commit` 한 줄이 있다", "cmd": ["sh", "-c", "[ \\"$(wc -l < /tmp/incoming.txt)\\" -eq 1 ] && grep -q \\"mate commit\\" /tmp/incoming.txt"]}, {"label": "작업 폴더에는 아직 mate.txt 가 없다 (합치지 않았다)", "cmd": ["sh", "-c", "[ ! -f /tmp/proj/mate.txt ]"]}]', '[{"title": "Git 공식 문서", "url": "https://git-scm.com/docs"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 54 AND order_index = 9);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 54, 10, 'push 가 거절되었을 때 풀기', '`/tmp/proj` 에는 내 커밋(`my commit`)이 있고, 그 사이 팀원도 원격에 커밋(`mate commit`)을 올려서 `git push` 가 **거절**됩니다. 팀원의 작업을 지우지 않고 **두 커밋이 모두 원격 `main` 에 올라가게** 하세요.', '`git push` 로 거절 메시지를 먼저 확인해 보세요. 해결은 받아서 합친 뒤 다시 올리는 것입니다. `git pull` 이 "어떻게 합칠지 지정하라"고 하면 도움말(`git pull --help`)에서 병합(`--no-rebase`)과 재배치(`--rebase`) 중 하나를 고르세요. 병합 커밋 편집기가 열리면 저장·종료합니다.
확인: `git log --oneline --graph`', 'cd /tmp/proj
git pull --no-rebase --no-edit
git push

# 먼저 원격 작업을 받아 합친 뒤 올린다
# --force 로 밀어붙이면 팀원 커밋이 사라질 수 있다', '["sh", "-c", "git config --global user.name tester && git config --global user.email tester@example.com && git config --global init.defaultBranch main && rm -rf /tmp/remote.git /tmp/seed /tmp/proj /tmp/work /tmp/mate && git init -q --bare /tmp/remote.git && git clone -q /tmp/remote.git /tmp/seed 2>/dev/null && cd /tmp/seed && printf ''readme\\\\n'' > README.md && git add . && git commit -qm init && git push -q origin main && cd /tmp && git clone -q /tmp/remote.git /tmp/proj && git clone -q /tmp/remote.git /tmp/mate && cd /tmp/mate && echo m > mate.txt && git add . && git commit -qm ''mate commit'' && git push -q origin main && cd /tmp && cd /tmp/proj && echo me > me.txt && git add . && git commit -qm ''my commit''"]', '["sh", "-c", "( git --git-dir=/tmp/remote.git log -n 5 --format=%s main | grep -qx \\"mate commit\\" ) && ( git --git-dir=/tmp/remote.git log -n 5 --format=%s main | grep -qx \\"my commit\\" ) && ( cd /tmp/proj && git fetch -q && [ \\"$(git rev-parse HEAD)\\" = \\"$(git rev-parse origin/main)\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "원격 main 에 `mate commit` 이 있다", "cmd": ["sh", "-c", "git --git-dir=/tmp/remote.git log -n 5 --format=%s main | grep -qx \\"mate commit\\""]}, {"label": "원격 main 에 `my commit` 도 있다", "cmd": ["sh", "-c", "git --git-dir=/tmp/remote.git log -n 5 --format=%s main | grep -qx \\"my commit\\""]}, {"label": "내 main 과 원격이 같다", "cmd": ["sh", "-c", "cd /tmp/proj && git fetch -q && [ \\"$(git rev-parse HEAD)\\" = \\"$(git rev-parse origin/main)\\" ]"]}]', '[{"title": "Git 공식 문서", "url": "https://git-scm.com/docs"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 54 AND order_index = 10);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 54, 11, '합쳐서 쓰기: 복제하고 브랜치로 작업해 올리기', '원격 `/tmp/remote.git` 을 `/tmp/work` 로 복제하세요. 그 안에서 **`feature/docs`** 브랜치를 만들어 `docs.txt` 를 **`add docs`** 로 커밋하고, 브랜치를 원격에 올리면서 추적 연결까지 하세요. 원격 `main` 은 바뀌면 안 됩니다.', '`clone` → `switch -c` → 작업·`add`·`commit` → `push -u origin 브랜치` 순서입니다.', 'git clone /tmp/remote.git /tmp/work
cd /tmp/work
git switch -c feature/docs
echo docs > docs.txt
git add docs.txt
git commit -m "add docs"
git push -u origin feature/docs', '["sh", "-c", "git config --global user.name tester && git config --global user.email tester@example.com && git config --global init.defaultBranch main && rm -rf /tmp/remote.git /tmp/seed /tmp/proj /tmp/work /tmp/mate && git init -q --bare /tmp/remote.git && git clone -q /tmp/remote.git /tmp/seed 2>/dev/null && cd /tmp/seed && printf ''readme\\\\n'' > README.md && git add . && git commit -qm init && git push -q origin main && cd /tmp"]', '["sh", "-c", "( git -C /tmp/work rev-parse --git-dir >/dev/null 2>&1 ) && ( [ \\"$(git --git-dir=/tmp/remote.git log -n 5 --format=%s feature/docs | head -n 1)\\" = \\"add docs\\" ] ) && ( [ \\"$(git -C /tmp/work rev-parse --abbrev-ref feature/docs@{upstream})\\" = origin/feature/docs ] ) && ( [ \\"$(git --git-dir=/tmp/remote.git log -n 5 --format=%s main | head -n 1)\\" = init ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "/tmp/work 가 복제되었다", "cmd": ["sh", "-c", "git -C /tmp/work rev-parse --git-dir >/dev/null 2>&1"]}, {"label": "원격에 feature/docs 가 있고 최신 커밋이 `add docs` 이다", "cmd": ["sh", "-c", "[ \\"$(git --git-dir=/tmp/remote.git log -n 5 --format=%s feature/docs | head -n 1)\\" = \\"add docs\\" ]"]}, {"label": "upstream 이 연결되었다", "cmd": ["sh", "-c", "[ \\"$(git -C /tmp/work rev-parse --abbrev-ref feature/docs@{upstream})\\" = origin/feature/docs ]"]}, {"label": "원격 main 은 그대로 `init` 하나다", "cmd": ["sh", "-c", "[ \\"$(git --git-dir=/tmp/remote.git log -n 5 --format=%s main | head -n 1)\\" = init ]"]}]', '[{"title": "Git 공식 문서", "url": "https://git-scm.com/docs"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 54 AND order_index = 11);
